// 各イベントに一意のslugを付与（詳細ページのルーティングに使用）
// 既存の出来事の間に後から追加する出来事は、明示的なslugを持たせて連番から外す（既存URLを変えないため）
ERAS.forEach((era) => {
  let i = 0;
  era.events.forEach((ev) => {
    if (!ev.slug) ev.slug = `${era.id}--${i++}`;
  });
});

export function findEventBySlug(slug) {
  for (const era of ERAS) {
    const event = era.events.find((ev) => ev.slug === slug);
    if (event) return { event, era };
  }
  return null;
}

// 全イベントを年表順に並べたフラットな配列（前後イベントの取得に使用）
const FLAT_EVENTS = ERAS.flatMap((era) => era.events.map((event) => ({ event, era })));

// 指定したslugの次のイベントを返す（最後のイベントの場合はnull）
export function getNextEvent(slug) {
  const idx = FLAT_EVENTS.findIndex((item) => item.event.slug === slug);
  if (idx === -1 || idx === FLAT_EVENTS.length - 1) return null;
  return FLAT_EVENTS[idx + 1];
}

// 指定したslugの前のイベントを返す（最初のイベントの場合はnull）
export function getPrevEvent(slug) {
  const idx = FLAT_EVENTS.findIndex((item) => item.event.slug === slug);
  if (idx <= 0) return null;
  return FLAT_EVENTS[idx - 1];
}

// 指定した王朝内に登場する人物（heritage type: figure）を名前で重複排除し、
// 各人物が関連する出来事（年・タイトル・slug）の一覧とともに返す
export function getEraFigures(era) {
  const map = new Map();
  era.events.forEach((ev) => {
    (ev.heritage || []).forEach((h) => {
      if (h.type !== "figure") return;
      const key = stripRuby(h.name);
      if (!map.has(key)) {
        map.set(key, { ...h, events: [] });
      }
      map.get(key).events.push({ slug: ev.slug, year: ev.year, title: ev.title });
    });
  });
  return Array.from(map.values());
}

// サイト内検索用に、全イベントをルビ除去済みのフラットなインデックスへ変換する
export function buildSearchIndex() {
  return ERAS.flatMap((era) =>
    era.events.map((ev) => ({
      slug: ev.slug,
      eraId: era.id,
      eraName: era.name,
      year: ev.year,
      title: stripRuby(ev.title),
      summary: stripRuby(ev.summary),
      category: ev.category,
      figures: (ev.heritage || []).filter((h) => h.type === "figure").map((h) => stripRuby(h.name)),
    }))
  );
}
